"""English documentation content; code examples reuse the canonical snippets."""
import re


def english_pages(zh):
    source = {slug: sections for slug, _, _, sections in zh}
    def example(slug, section):
        return ''.join(re.findall(r'<pre>.*?</pre>', source[slug][section][1], re.S))
    return [
        ('', 'Documentation', 'Build a Business Agent, from its first contract to governed execution and platform integration.', [
            ('Start here', '<p>Brivya is open Business-to-Agent infrastructure. It models real business capabilities as typed contracts and connects REST, MCP and distribution ecosystems through one governed runtime.</p><p>New to Brivya? Start with the CLI, then explore the architecture and Restaurant reference. Existing TypeScript applications can begin with the SDK and protocol adapters.</p>'),
            ('Developer journey', '<ol><li><a href="/docs/quickstart/">Quick Start</a>: generate and validate a business Manifest.</li><li><a href="/docs/architecture/">Architecture and safety</a>: understand contracts, runtime and projections.</li><li><a href="/docs/sdk/">TypeScript SDK</a>: use canonical types and execution.</li><li><a href="/docs/adapters/">Protocols and platforms</a>: connect REST, MCP and reference distribution profiles.</li><li><a href="/docs/restaurant/">Restaurant reference</a>: run the existing end-to-end contract tests.</li></ol>'),
            ('Current version', '<p>The public release is <code>0.1.0-alpha.1</code>. All 14 public npm packages use the <code>next</code> dist-tag. APIs are pre-stable. These docs describe the Alpha baseline, not a hosted service or a third-party publication guarantee.</p><p><a href="/docs/releases/">Explore versions and packages →</a></p>'),
        ]),
        ('quickstart', 'Quick Start', 'Create your first business contract and validate the local development configuration.', [
            ('Prerequisites', '<p>Use Node.js 20 or newer and npm. The local CLI flow does not require a cloud account, LLM API key or database.</p>'+example('quickstart',0)),
            ('Create a business contract', example('quickstart',1)+'<p><code>init</code> creates <code>business.agent.yaml</code>; <code>validate</code> checks the Manifest; <code>inspect</code> shows the resolved definition; <code>dev</code> validates and displays local configuration.</p><aside class="doc-note">The generated Manifest is a contract scaffold. It is not connected to a real business system. CLI dev does not start an HTTP server or replace BusinessRuntime execution.</aside>'),
            ('Edit and observe', '<p>Maintain business identity, capabilities, protocols and security requirements in the generated Manifest. Inspect the scaffold before editing and keep validation in your workflow. To observe changes:</p>'+example('quickstart',2)+'<p>You can pass an explicit Manifest path to validate, inspect and dev. Init does not silently overwrite existing files.</p>'),
            ('Connect real capabilities', '<p>Use the SDK to register contracts, supply authorization and policy, implement Connectors and attach protocol adapters. Discovering a capability never grants permission to mutate business state.</p><p>Continue with the <a href="/docs/sdk/">SDK</a> or the <a href="/docs/restaurant/">Restaurant reference</a>.</p>'),
        ]),
        ('architecture', 'Architecture and safety', 'One business truth, many projections. Every mutation follows the same governed execution path.', [
            ('Layers', '<div class="doc-flow"><div>AI platforms and Agent Hosts</div><span>↓</span><div>DistributionProfile · REST / MCP</div><span>↓</span><div>Canonical Business Agent · BusinessRuntime</div><span>↓</span><div>Connector · ERP / CRM / POS / Business APIs</div></div><p>Manifests, resources, capabilities and events define the canonical contract. Protocol adapters project invocation; distribution profiles project discovery, experience and packaging. Business authority stays in the contracts and runtime.</p>'),
            ('Mutation path', '<pre><code>Validate → Authorize → Policy → Approval when required\n→ Idempotency → Connector → Transaction / Audit / Event</code></pre><p>BusinessRuntime owns safety semantics. LLMs do not directly mutate business databases. Adapters cannot invoke Connectors to bypass authorization, policy or approval.</p>'),
            ('Identity and authorization', '<ul><li>Agent Identity is not Authorization: recognizing a caller does not grant unrestricted execution.</li><li>Discovery is not Authorization: a Manifest describes capabilities, not mutation permission.</li><li>Platform Identity supplies context and still requires business authorization.</li><li>UI Confirmation is not an ApprovalRecord: a client confirmation does not replace trusted evidence.</li></ul><p>Protocol and experience projections must preserve risk, approval, permissions, idempotency and audit semantics.</p>'),
            ('Core modules', '<table><thead><tr><th>Module</th><th>Responsibility</th></tr></thead><tbody><tr><td>Core / Manifest</td><td>Typed contracts, parsing and validation</td></tr><tr><td>Policy / Runtime</td><td>Policy and governed execution</td></tr><tr><td>Experience / Distribution</td><td>Shared interaction semantics and projections</td></tr><tr><td>SDK / CLI</td><td>Developer APIs and local contract tools</td></tr><tr><td>Adapters / Connectors</td><td>Protocol entry points and business boundaries</td></tr></tbody></table>'),
        ]),
        ('sdk', 'TypeScript SDK', 'Reuse public business types, Manifest validation and the canonical runtime.', [
            ('Install', example('sdk',0)+'<p>The SDK is a facade over Core, Manifest, Policy and Runtime. It does not introduce another authorization model or runtime truth.</p>'),
            ('Load a Manifest', '<p>Read a Manifest generated by CLI init, then use canonical parsing and validation:</p>'+example('sdk',1)+'<p>Handle parsing and validation errors rather than executing with an invalid Manifest.</p>'),
            ('Runtime and types', example('sdk',2)+'<p>BusinessRuntime and CapabilityRegistry reference the canonical implementations. Execution also needs capability registration, Connectors, trusted authorization context and runtime dependencies. Importing the SDK alone does not create a business service.</p>'),
            ('Integration order', '<ol><li>Define capability inputs, outputs and safety requirements.</li><li>Register contracts with CapabilityRegistry.</li><li>Provide Connectors plus policy, approval, idempotency and audit implementations.</li><li>Construct identity and delegation context on a trusted server.</li><li>Execute through BusinessRuntime or adapters attached to that same runtime.</li></ol><p>See the <a href="/docs/restaurant/">Restaurant reference</a> for execution tests and the <a href="/docs/adapters/">adapter guide</a> for protocol integration.</p>'),
        ]),
        ('adapters', 'Protocols and platforms', 'REST and MCP share the runtime. Distribution profiles reuse canonical business semantics.', [
            ('REST boundary', '<p>The REST adapter is an HTTP-framework-neutral execution projection:</p>'+example('adapters',0)+'<p>Protocol metadata uses X-Brivya-Capability-Version, X-Request-Id, X-Correlation-Id, X-Causation-Id and Idempotency-Key headers. The body cannot assert trusted identity or approval state.</p><p>The hosting HTTP layer verifies authentication or session state and supplies a trusted RestSecurityContext. The adapter constructs an ActionRequest and calls BusinessRuntime.</p>'),
            ('MCP projection', '<p>The capability <code>order.create@0.1.0</code> becomes the tool <code>brivya.order.create.v0.1.0</code>. Input and output JSON Schemas pass through to the MCP SDK.</p><p>The hosting transport/auth layer supplies a trusted McpContextResolver for verified identity, delegation, approvals and correlation metadata. Tool arguments are business input only. MCP annotations are hints, not authorization.</p><aside class="doc-note">The default context contains only an untrusted Agent actor. Protected capabilities fail closed without a trusted resolver.</aside>'),
            ('WorkBuddy and WeChat AI', '<table><thead><tr><th>Reference projection</th><th>Output</th></tr></thead><tbody><tr><td>WorkBuddy</td><td>connector-meta.json, mcp.json, skills/business/SKILL.md</td></tr><tr><td>WeChat AI</td><td>SKILL.md, mcp.json, runtime-bridge.json, components and registration patch</td></tr></tbody></table><p>These are reference generators and conformance baselines. Production publication still requires current official platform requirements, qualification and review. Third-party fields and APIs are not guaranteed stable.</p>'),
            ('Before integration', '<ul><li>Preserve schemas, risk and permission requirements.</li><li>Keep canonical approval requirements for high-risk actions.</li><li>Preserve idempotency and audit across protocols.</li><li>Never elevate client identity or UI confirmation into trusted authorization evidence.</li></ul><p>SemanticExperience describes shared interactions; platform renderers provide native presentation while actions remain bound to canonical Capability IDs.</p>'),
        ]),
        ('extensions', 'Extension Host', 'Declare permissions explicitly and extend capabilities through a scoped Host API.', [
            ('Alpha baseline', '<p>The baseline includes Extension Manifest / Package, permission grants, expansion detection, install plans, Registry Client contracts, and worker / remote boundaries.</p><p>These framework contracts do not imply an existing hosted Registry or third-party marketplace.</p>'),
            ('Effective permissions', '<pre><code>Requested permissions ∩ Tenant policy ∩ Administrator grant\n= Effective permissions</code></pre><p>Declaring a permission does not grant it. A new version that expands privileges requires approval again. The host grants only the permitted intersection.</p>'),
            ('Execution and secrets', '<pre><code>Extension → Host API\n→ Canonical Brivya Runtime / Governed platform service</code></pre><p>The Host API enforces permissions. Secrets use opaque bindings rather than raw values. There is no raw secret-read Host API.</p>'),
            ('Current limits', '<p>Phase 1 models worker and remote execution. WASM is deferred and arbitrary third-party in-process execution is outside the baseline. Validate host isolation, authorization and outbound policy before production use.</p><p><a href="/docs/architecture/">Review runtime safety →</a></p>'),
        ]),
        ('restaurant', 'Restaurant reference', 'Follow discovery, reservations, orders and payment requests through deterministic contract tests.', [
            ('Capabilities', '<table><thead><tr><th>Capability</th><th>Business step</th></tr></thead><tbody><tr><td>menu.search</td><td>Search the menu</td></tr><tr><td>availability.check</td><td>Check availability</td></tr><tr><td>reservation.create</td><td>Create a reservation</td></tr><tr><td>order.create</td><td>Create an order</td></tr><tr><td>payment.request</td><td>Request payment</td></tr></tbody></table><p>REST and MCP use the same contracts and BusinessRuntime. The reference uses mock Connectors without an LLM provider or real payment SDK dependency.</p>'),
            ('Get and run', example('restaurant',1)+'<p>The current repository has no committed lockfile, so use the same npm install approach as CI. The root command builds, typechecks and tests, including the Restaurant RST-001..RST-024 contract matrix.</p>'),
            ('Run reference tests only', example('restaurant',2)+'<p>Build all workspaces first to prepare cross-package dependencies. Then run the compiled reference suite, covering execution, safety rejection and audit behavior with deterministic data.</p>'),
            ('Reading path', '<ul><li><code>examples/restaurant/src/manifest.ts</code>: business identity and capability declarations.</li><li><code>examples/restaurant/src/capabilities.ts</code>: capability definitions.</li><li><code>examples/restaurant/test/</code>: end-to-end evidence.</li><li><code>connectors/mock/</code>: mock business integration.</li></ul><aside class="doc-note">payment.request is a business payment request, not a connection to a real payment channel. The bootstrap URL is example identity, not a hosted live demo.</aside>'),
        ]),
        ('releases', 'Versions and packages', 'Understand the public Alpha modules, installation and stability boundaries.', [
            ('v0.1.0-alpha.1', '<p>The first public Alpha was released on October 3, 2026. All 14 public npm packages use <code>0.1.0-alpha.1</code> under the <code>next</code> dist-tag. Pin versions explicitly while APIs remain pre-stable.</p>'+example('releases',0)),
            ('Public packages', source['releases'][1][1]),
            ('Capabilities and limits', '<p>The baseline includes typed contracts, governed runtime, REST / MCP, reference distribution profiles, CLI / SDK, Restaurant E2E and Extension Host. The root workspace and Restaurant example are not published npm packages.</p><p>This version does not promise hosted Runtime, Registry, enterprise identity or automatic production platform publication. npm OIDC migration concerns release governance, not installation or website use.</p>'),
            ('Before upgrading', '<ul><li>Review release notes for API and Manifest compatibility.</li><li>Run business contract, permission, approval, idempotency and adapter tests.</li><li>Keep canonical package versions aligned.</li><li>Do not assume Alpha changes are stable compatibility guarantees.</li></ul>'),
        ]),
        ('contributing', 'Contributing and security', 'Help improve business contracts, developer tools and platform conformance.', [
            ('Contributing', '<p>Contribute through issues and Pull Requests in the public implementation repository. Discuss substantial changes first. Preserve protocol and model neutrality, typed capabilities and explicit policy boundaries.</p><ol><li>Create a feature branch for a focused change.</li><li>Add tests and public documentation for behavior changes.</li><li>Run npm run ci and relevant release checks.</li><li>Describe the problem, behavior, validation and compatibility in a PR.</li></ol>'),
            ('Security reports', '<p>Report potential vulnerabilities privately through the channels in SECURITY.md. Never post credentials, customer data or sensitive vulnerability details in public issues.</p><p><a href="https://github.com/brivya/brivya/blob/main/SECURITY.md">Security reporting channels ↗</a></p>'),
            ('License and brand', '<p>The public framework uses Apache-2.0. Brivya names and branding are governed separately by trademark policy. Framework use does not grant additional platform or brand permissions.</p><p><a href="https://github.com/brivya/brivya/blob/main/LICENSE">Read the license ↗</a></p>'),
        ]),
    ]
